begin;
set local row_security=on;
insert into auth.users(id) values('50190000-0000-4000-8000-000000000001');
insert into public.companies(id,name) values('50190000-0000-4000-8000-000000000010','Fictional SOP company');
insert into public.profiles(id,company_id,full_name,role,status) values('50190000-0000-4000-8000-000000000001','50190000-0000-4000-8000-000000000010','Fictional SOP editor','admin','active');
create or replace function auth.uid() returns uuid language sql stable as $$select '50190000-0000-4000-8000-000000000001'::uuid$$;
grant usage on schema public,auth to authenticated;
grant select on public.profiles,public.sop_video_projects,public.sop_video_evidence to authenticated;
create function public.sop_fixture_fail() returns trigger language plpgsql as $$begin if current_setting('sop.fixture_failure',true)='yes' then raise exception 'Synthetic evidence failure';end if;return new;end $$;
create trigger sop_fixture_fail before insert on public.sop_video_evidence for each row execute function public.sop_fixture_fail();
set local role authenticated;
do $$declare workspace_id text:='50190000-0000-4000-8000-000000000099';company uuid:='50190000-0000-4000-8000-000000000010';r jsonb;body jsonb;old_time timestamptz;begin
 body:=jsonb_build_object('company_id',company,'workspace','{"task":{"title":"","department":"Fictional workshop","risk":"High","authorId":"Fictional person","version":"Rev 03","reviewDate":"2027-01-01","ppe":["Safety glasses"],"description":"Fictional task"},"frames":[],"step":2}'::jsonb,'source_file_name','fictional.webm','consent_confirmed',false);
 r:=public.save_sop_workspace(workspace_id,null,body);
 if r->>'title'<>'Untitled SOP draft' or r->>'processing_status'<>'draft' or (r->>'consent_confirmed')::boolean or r->>'source_storage_path' is not null then raise exception 'Incomplete draft asserted consent, upload or approval';end if;
 if r->'processing_detail'->'workspace'->'task'->>'version'<>'Rev 03' or r->'processing_detail'->'workspace'->'task'->'ppe'->>0<>'Safety glasses' then raise exception 'Task metadata lost';end if;
 begin perform public.save_sop_workspace(workspace_id,null,body);raise exception 'Uncertain retry duplicated draft';exception when raise_exception then if sqlerrm not like 'Workspace changed%' then raise;end if;end;
 if (select count(*) from public.sop_video_projects where id=workspace_id)<>1 then raise exception 'Draft duplicated';end if;
 body:=jsonb_set(body,'{workspace,frames}','[{"narration":"Fictional manual instruction","source_type":"reviewer_added","review_state":"pending"}]');
 r:=public.save_sop_workspace(workspace_id,(r->>'updated_at')::timestamptz,body,true);
 if r->>'processing_status'<>'ready_for_review' or (select count(*) from public.sop_video_evidence where project_id=workspace_id)<>1 then raise exception 'Evidence draft not saved';end if;
 old_time:=(r->>'updated_at')::timestamptz;
 body:=jsonb_set(body,'{workspace,frames,0,dataUrl}','"data:image/png;base64,AA=="');
 begin perform public.save_sop_workspace(workspace_id,old_time,body);raise exception 'Captured image saved without authorisation';exception when raise_exception then if sqlerrm not like 'Confirm recording%' then raise;end if;end;
 body:=jsonb_set(body,'{consent_confirmed}','true');perform set_config('sop.fixture_failure','yes',true);
 begin perform public.save_sop_workspace(workspace_id,old_time,body,true);raise exception 'Partial evidence save committed';exception when raise_exception then if sqlerrm<>'Synthetic evidence failure' then raise;end if;end;
 if (select updated_at from public.sop_video_projects where id=workspace_id) is distinct from old_time or (select count(*) from public.sop_video_evidence where project_id=workspace_id)<>1 then raise exception 'Failed evidence replacement lost prior work';end if;
 perform set_config('sop.fixture_failure','no',true);r:=public.save_sop_workspace(workspace_id,old_time,body,true);
 if not exists(select 1 from public.sop_video_evidence where project_id=workspace_id and image_reference='data:image/png;base64,AA==') then raise exception 'Captured image not retained';end if;
 begin perform public.save_sop_workspace(workspace_id,(r->>'updated_at')::timestamptz,jsonb_set(body,'{company_id}','"50190000-0000-4000-8000-000000000020"'));raise exception 'Foreign company write accepted';exception when insufficient_privilege then null;end;
 body:=jsonb_set(body,'{workspace,frames,0,dataUrl}','"data:image/svg+xml;base64,AA=="');
 begin perform public.save_sop_workspace(workspace_id,(r->>'updated_at')::timestamptz,body);raise exception 'Active image content accepted';exception when raise_exception then if sqlerrm not like 'Evidence images%' then raise;end if;end;
end $$;
reset role;
update public.sop_video_projects set processing_status='approved' where id='50190000-0000-4000-8000-000000000099';
set local role authenticated;
do $$declare r public.sop_video_projects;begin
 select * into r from public.sop_video_projects where id='50190000-0000-4000-8000-000000000099';
 begin perform public.save_sop_workspace(r.id,r.updated_at,jsonb_build_object('company_id',r.company_id,'workspace','{"task":{"title":"Attempted overwrite"},"frames":[]}'::jsonb));raise exception 'Approved workspace overwritten';exception when raise_exception then if sqlerrm not like 'This workspace is in review%' then raise;end if;end;
end $$;
reset role;
rollback;
